import assert from 'node:assert/strict'

// Actual production App/MeetingMode/composer; provider and OS capture remain fixtures.
export async function checkMeetingComposer({ ev, click, change, frames, wait, send, shot }) {
  if (await ev("!document.querySelector('.meeting-transcript')")) { await click('Hội thoại'); await frames() }
  await send('Emulation.setDeviceMetricsOverride', { width: 400, height: 620, deviceScaleFactor: 1, mobile: false }); await frames()
  await click('Chat'); await frames()
  assert.ok(await ev("{const t=document.querySelector('.meeting-transcript');t.getBoundingClientRect().height>=180&&getComputedStyle(t).overflowY==='auto'&&!t.closest('.meeting-workspace-controls')}"), 'Transcript keeps 180px and its own scroll outside shrinking controls')
  assert.ok(await ev("document.querySelector('.meeting-answer').getBoundingClientRect().height>=300"), 'Opening transcript cannot shrink Answer')
  assert.ok(await ev("document.querySelector('.meeting-transcript').scrollHeight>document.querySelector('.meeting-transcript').clientHeight"), 'Long transcript scrolls inside the panel')
  await ev("document.querySelector('.meeting-transcript').scrollIntoView({block:'center'})"); await frames()
  await shot('meeting-transcript-min-height-400px')
  await click('Chat'); await click('Hội thoại'); await frames()
  await ev("document.querySelector('.meeting-workspace').scrollTop=0")
  await send('Emulation.setDeviceMetricsOverride', { width: 880, height: 740, deviceScaleFactor: 1, mobile: false }); await frames()
  await ev("document.querySelector('.meeting-mic-toggle').click()"); await frames()
  assert.equal(await ev('window.fixture.micMuted'), true)
  assert.equal(await ev("document.querySelector('.meeting-mic-toggle').getAttribute('aria-pressed')"), 'true')
  await ev("window.fixture.draft({speaker:'Me',text:'PRIVATE_MUTED_DRAFT',ts:1});window.fixture.draft({speaker:'Others',text:'Remote unaffected',ts:1})")
  await frames()
  assert.equal(await ev("document.querySelector('.meeting-workspace').textContent.includes('PRIVATE_MUTED_DRAFT')"), false)
  assert.ok(await ev("document.querySelector('.meeting-question-strip').textContent.includes('Remote unaffected')"))
  await click('Thu gọn'); await wait("document.querySelector('button[title=\"Expand\"]')")
  await ev("document.querySelector('button[title=\"Expand\"]').click()"); await frames()
  assert.equal(await ev("document.querySelector('.meeting-mic-toggle').getAttribute('aria-pressed')"), 'true')
  await ev("document.querySelector('.meeting-mic-toggle').click()"); await frames()
  assert.equal(await ev('window.fixture.micMuted'), false)
  await click('Chat'); await frames()
  assert.equal(await ev("document.querySelector('.meeting-composer').hidden"), false)
  assert.equal(await ev("[...document.querySelectorAll('button')].find(b=>b.textContent==='Gửi câu hỏi').disabled"), true)
  const code = 'Explain and fix:\nfunction sum(a) { return a[0] + a[1] }'
  await change('.meeting-composer textarea', code); await frames()
  await ev('window.fixture.failQuestion=true')
  await click('Gửi câu hỏi'); await frames()
  assert.equal(await ev("document.querySelector('.meeting-composer textarea').value"), code, 'Failed send keeps user draft')
  await ev('window.fixture.failQuestion=false;window.fixture.delayQuestion=true')
  await click('Gửi câu hỏi'); await wait('window.fixture.releaseQuestion')
  await ev("document.querySelector('.meeting-mic-toggle').click()"); await frames()
  assert.equal(await ev('window.fixture.micMuted'), true, 'Mic remains controllable while AI is generating')
  assert.equal(await ev("document.querySelector('.meeting-toolbar .meeting-primary').disabled"), true)
  assert.equal(await ev('window.fixture.questions.at(-1).meetingId'), 'interview-fixture')
  await ev('window.fixture.releaseQuestion();window.fixture.delayQuestion=false'); await frames()
  await wait("document.querySelector('.meeting-composer textarea').value===''")
  await click('Screenshot'); await wait("document.querySelector('.meeting-image-preview')")
  assert.equal(await ev('window.fixture.captures'), 1)
  assert.equal(await ev('window.fixture.questions.length'), 2, 'Capture does not send automatically')
  await send('Emulation.setDeviceMetricsOverride', { width: 400, height: 620, deviceScaleFactor: 1, mobile: false }); await frames()
  assert.equal(await ev('document.documentElement.scrollWidth>innerWidth'), false)
  await ev("document.querySelector('.meeting-composer footer button:last-child').scrollIntoView({block:'nearest'})"); await frames()
  assert.ok(await ev("{const r=document.querySelector('.meeting-composer footer button:last-child').getBoundingClientRect();r.left>=0&&r.right<=innerWidth&&r.bottom<=innerHeight}"), 'Send remains reachable via controls scroll at 400px')
  assert.ok(await ev("{const r=document.querySelector('.meeting-answer').getBoundingClientRect();r.height>=300&&r.top>=0&&r.bottom<=innerHeight}"), 'Answer stays at least 300px and visible with image composer open')
  assert.ok(await ev("{const r=document.querySelector('.meeting-answer-content').getBoundingClientRect();r.height>=220}"), 'Readable answer content has its own scroll area')
  await shot('meeting-chat-image-400px')
  await send('Emulation.setDeviceMetricsOverride', { width: 880, height: 740, deviceScaleFactor: 1, mobile: false }); await frames()
  await click('Bỏ ảnh'); await frames()
  assert.equal(await ev("!!document.querySelector('.meeting-image-preview')"), false)
  assert.equal(await ev('window.fixture.discards.length'), 1)
  await click('Screenshot'); await wait("document.querySelector('.meeting-image-preview')")
  // Mic failure must not block explicit image/coding questions.
  await ev('window.fixture.failMicFlush=true;window.fixture.flushBeforeImage=window.fixture.flushes')
  await click('Gửi câu hỏi'); await wait("!document.querySelector('.meeting-image-preview')")
  assert.equal(await ev('window.fixture.questions.at(-1).imageId'), '11111111-1111-4111-8111-111111111111')
  assert.equal(await ev('window.fixture.questions.at(-1).question'), '')
  assert.equal(await ev('window.fixture.flushes'), await ev('window.fixture.flushBeforeImage'))
  await change('.meeting-composer textarea', 'Optimize the previous solution'); await frames()
  await ev("document.querySelector('.meeting-composer textarea').dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',ctrlKey:true,bubbles:true}))")
  await wait("document.querySelector('.meeting-composer textarea').value===''")
  assert.equal(await ev('window.fixture.questions.at(-1).imageId'), undefined, 'Old image is not resent implicitly')
  assert.equal(await ev('window.fixture.flushes'), await ev('window.fixture.flushBeforeImage'), 'Typed coding follow-up also bypasses mic flush')
  await click('Answer'); await frames()
  assert.ok(await ev("document.querySelector('.meeting-workspace').textContent.includes('Synthetic mic flush failure')"), 'Regular Answer retains mic flush')
  await ev('window.fixture.failMicFlush=false')
  assert.equal(await ev('window.fixture.starts'), 1)
  assert.equal(await ev('window.fixture.stops'), 0)
  await click('Chat'); await frames()
}
